with with_gaps as (select *, case when lag(event_time) over (partition by session_id order by event_time, id) is null or event_time > lag(event_time) over (partition by session_id order by event_time, id) + interval '90' day then 1 else 0 end as session_start_flag from web_events), islands as (select *, sum(session_start_flag) over (partition by session_id order by event_time, id rows between unbounded preceding and current row) as session_id_2 from with_gaps) select session_id, count(*) filter (where page = '/checkout') as checkout_rows, count(case when event_type = 'page_view' then 1 end) as page_view_count, count(*) as cnt, round(sum(session_start_flag) / nullif(count(case when event_type = 'search' then 1 end), 0), 2) as session_start_flag_per_search from islands group by session_id
